script:
(function () {
  'use strict';
  // Value of an employer HSA contribution and match to the employee, for one year:
  //   match = min(match % x your contribution, match cap); employer total = flat + match
  //   (employer + you) is held to the 2026 limit: the employer's money first, then yours.
  //   tax saved = your payroll contribution x (federal + state)
  //             + 6.2% on the part below the Social Security wage base
  //             + 1.45% Medicare (+0.9% on the part above $200,000)
  //   value to you = employer total + tax saved
  //   pay raise it equals = value / (1 - federal - state - your marginal FICA rate), because
  //   employer HSA money and your payroll contributions skip income tax and FICA.
  //   employer money after N years = E x (1 + r) x ((1 + r)^N - 1) / r (deposited at the start
  //   of each year). Employer's own FICA saved = 6.2% (below the wage base) + 1.45% of yours.
  // CHECKS (Node, scratch tests): defaults ($70,000, $500 flat, 50% match up to $750, you
  // $1,000, 22% + 5%): match $500, employer $1,000, tax saved $1,000 x 34.65% = $346.50, value
  // $1,346.50, raise $1,346.50 / 0.6535 = $2,060.44, real cost $653.50, instant return
  // 846.50 / 653.50 = 129.5%; you $1,500 -> full $750 match; self-only you $5,000 -> capped
  // at $4,400 - 500 - 750 = $3,150; salary $185,000, you $1,000 -> SS saved only on $500
  // below the $184,500 base ($31); $1,000 a year for 10 years at 5% -> $13,206.79.
  // ---- 2026 LIMITS (calendar year 2026) -------------------------------------------------------
  // HSA: IRS Rev. Proc. 2025-19 (IRC 223), repeated in IRS Pub. 969 and Pub. 15-B (2026);
  // catch-up IRC 223(b)(3)(B), $1,000 at 55 or older. Pub. 15-B: employer HSA contributions
  // (including cafeteria-plan salary reductions) are free of income tax, Social Security and
  // Medicare. FICA: 6.2% / 1.45% (IRC 3101, 3111), Additional Medicare 0.9% over $200,000
  // (IRC 3101(b)(2)); 2026 Social Security wage base $184,500 (SSA 2026 COLA fact sheet).
  var HSA = { year: 2026, limit: { self: 4400, family: 8750 }, catchUp55: 1000 };
  var FICA = { ss: 0.062, medicare: 0.0145, addlMedicare: 0.009, addlStart: 200000, ssWageBase: 184500 };
  // --------------------------------------------------------------------------------------------

  function employerFor(you, p) {
    return Math.min(p.limit, p.flat + Math.min(p.matchRate * you, p.matchCap));
  }

  // Largest contribution up to `want` that keeps you + employer within the limit.
  function capYou(want, p) {
    if (want + employerFor(want, p) <= p.limit + 1e-9) return want;
    var lo = 0, hi = want;
    for (var k = 0; k < 60; k++) {
      var mid = (lo + hi) / 2;
      if (mid + employerFor(mid, p) <= p.limit + 1e-9) lo = mid; else hi = mid;
    }
    return lo;
  }

  function ficaSaved(salary, amount) {
    var after = Math.max(0, salary - amount);
    var ss = FICA.ss * (Math.min(salary, FICA.ssWageBase) - Math.min(after, FICA.ssWageBase));
    var med = FICA.medicare * (salary - after) +
              FICA.addlMedicare * (Math.max(0, salary - FICA.addlStart) - Math.max(0, after - FICA.addlStart));
    return { employee: ss + med, employer: ss + FICA.medicare * (salary - after) };
  }

  // p: limit, flat, matchRate, matchCap, salary, incomeRate (decimals); want = your contribution
  function value(want, p) {
    var you = capYou(want, p), er = employerFor(you, p), match = Math.max(0, er - Math.min(p.flat, p.limit));
    var fica = ficaSaved(p.salary, you), incTax = you * p.incomeRate, tax = incTax + fica.employee;
    return { you: you, er: er, flat: er - match, match: match, incTax: incTax, fica: fica.employee, tax: tax,
             erFica: fica.employer, total: er + tax, cost: you - tax, capped: want > you + 0.005 };
  }

  function marginalFica(salary) {
    return (salary < FICA.ssWageBase ? FICA.ss : 0) + FICA.medicare + (salary > FICA.addlStart ? FICA.addlMedicare : 0);
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 });
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var coverage = document.getElementById('heCoverage').value === 'family' ? 'family' : 'self';
    var salary = num('heSalary'), flat = num('heFlat'), matchRate = num('heMatchRate'), matchCap = num('heMatchCap'),
        want = num('heYou'), fed = parseFloat(document.getElementById('heFed').value), state = num('heState'),
        years = num('heYears'), ret = num('heReturn'), age55 = document.getElementById('heAge55').checked;
    var error = document.getElementById('heError'), msg = '';
    if ([salary, flat, matchRate, matchCap, want, fed, state, years, ret].some(isNaN) ||
        [salary, flat, matchRate, matchCap, want].some(function (v) { return v < 0; }))
      msg = 'Enter non-negative amounts in every field.';
    else if (matchRate > 500) msg = 'Enter an employer match from 0 to 500%.';
    else if (want > salary) msg = 'Your payroll contribution cannot be more than your salary.';
    else if (state < 0 || state > 15) msg = 'Enter a state tax rate from 0 to 15%.';
    else if (years < 1 || years > 40 || Math.round(years) !== years) msg = 'Enter a whole number of years from 1 to 40.';
    else if (ret < 0 || ret > 20) msg = 'Enter an investment return from 0 to 20%.';
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }

    var p = { limit: HSA.limit[coverage] + (age55 ? HSA.catchUp55 : 0), flat: flat, matchRate: matchRate / 100,
              matchCap: matchCap, salary: salary, incomeRate: fed / 100 + state / 100 };
    var v = value(want, p);
    var keep = 1 - p.incomeRate - marginalFica(salary);
    set('heTotal', money(v.total));
    set('heEmployer', money(v.er));
    set('heTax', money(v.tax));
    set('heRaise', keep > 0 ? money(v.total / keep) : '–');
    set('heFlatOut', money(v.flat));
    set('heMatchOut', money(v.match));
    set('heYouOut', money(v.you));
    set('heIncTax', money(v.incTax));
    set('heFica', money(v.fica));
    set('heNetCost', money(v.cost));
    set('heInstant', v.cost > 0.005 ? pct.format((v.match + v.tax) / v.cost) : '–');
    var r = ret / 100, grow = r > 0 ? v.er * (1 + r) * (Math.pow(1 + r, years) - 1) / r : v.er * years;
    set('heGrowLabel', 'Employer money after ' + years + ' year' + (years === 1 ? '' : 's') + ' invested');
    set('heGrow', money(grow));
    set('heErFica', money(v.erFica));

    var missed = document.getElementById('heMissed');
    var full = p.matchRate > 0 ? p.matchCap / p.matchRate : 0;
    var best = value(full, p);
    var showMiss = p.matchRate > 0 && p.matchCap > 0 && best.match > v.match + 0.5;
    missed.hidden = !showMiss;
    if (showMiss) missed.textContent = 'You are leaving ' + money(best.match - v.match) + ' of employer match unclaimed. Contributing ' +
        money(best.you) + ' a year (about ' + money(best.you / 26) + ' a paycheck on a biweekly schedule) gets the full match.';
    var capEl = document.getElementById('heCapped');
    capEl.hidden = !v.capped;
    if (v.capped) capEl.textContent = 'Your contribution plus your employer\'s cannot exceed the ' + HSA.year + ' limit of ' +
        money(p.limit) + ', so the results use ' + money(v.you) + ' for you.';

    var levels = [], maxYou = capYou(p.limit, p);
    for (var a = 0; a < maxYou - 0.005; a += 500) levels.push(a);
    levels.push(maxYou);
    if (full > 0 && full < maxYou && levels.indexOf(full) < 0) levels.push(full);
    if (levels.indexOf(v.you) < 0) levels.push(v.you);
    levels.sort(function (x, y) { return x - y; });
    var body = document.getElementById('heTable');
    body.textContent = '';
    levels.forEach(function (lv) {
      var x = value(lv, p), tr = document.createElement('tr'), tags = [];
      if (Math.abs(lv - v.you) < 0.005) tags.push('yours');
      if (Math.abs(lv - full) < 0.005 && full > 0) tags.push('full match');
      if (Math.abs(lv - maxYou) < 0.005) tags.push('limit');
      [money(x.you) + (tags.length ? ' (' + tags.join(', ') + ')' : ''), money(x.er), money(x.tax), money(x.cost), money(x.you + x.er), money(x.total)]
        .forEach(function (c) { var td = document.createElement('td'); td.textContent = c; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('heForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
